    "source": "/** DSU (union by size + path compression), teaching version. Elements are 0..n-1. */\npublic class DSU {\n    int[] parent, size;\n    int count; // number of disjoint sets\n\n    DSU(int n) {\n        parent = new int[n];\n        size = new int[n];\n        for (int i = 0; i < n; i++) { parent[i] = i; size[i] = 1; }\n        count = n;\n    }\n\n    /** Root of x; afterwards every node on the path points directly at the root. */\n    int find(int x) {\n        int root = x;\n        while (parent[root] != root) {\n            root = parent[root];\n        }\n        while (parent[x] != root) {\n            int next = parent[x];\n            parent[x] = root;\n            x = next;\n        }\n        return root;\n    }\n\n    /** Merge the sets of a and b. Returns true if they were different sets. */\n    boolean union(int a, int b) {\n        int ra = find(a), rb = find(b);\n        if (ra == rb) return false;\n        if (size[ra] < size[rb]) { int t = ra; ra = rb; rb = t; }\n        parent[rb] = ra;\n        size[ra] += size[rb];\n        count--;\n        return true;\n    }\n\n    boolean same(int a, int b) {\n        return find(a) == find(b);\n    }\n}\n",
