    "source": "/// DSU (union by size + path compression), teaching version. Elements are 0..n-1.\npub struct Dsu {\n    pub parent: Vec<usize>,\n    pub size: Vec<usize>,\n    pub count: usize, // number of disjoint sets\n}\n\nimpl Dsu {\n    pub fn new(n: usize) -> Self {\n        Dsu { parent: (0..n).collect(), size: vec![1; n], count: n }\n    }\n\n    /// Root of x; afterwards every node on the path points directly at the root.\n    pub fn find(&mut self, mut x: usize) -> usize {\n        let mut root = x;\n        while self.parent[root] != root {\n            root = self.parent[root];\n        }\n        while self.parent[x] != root {\n            let next = self.parent[x];\n            self.parent[x] = root;\n            x = next;\n        }\n        root\n    }\n\n    /// Merge the sets of a and b. Returns true if they were different sets.\n    pub fn union(&mut self, a: usize, b: usize) -> bool {\n        let (mut ra, mut rb) = (self.find(a), self.find(b));\n        if ra == rb { return false; }\n        if self.size[ra] < self.size[rb] { std::mem::swap(&mut ra, &mut rb); }\n        self.parent[rb] = ra;\n        self.size[ra] += self.size[rb];\n        self.count -= 1;\n        true\n    }\n\n    pub fn same(&mut self, a: usize, b: usize) -> bool {\n        self.find(a) == self.find(b)\n    }\n}\n",
